#!/bin/bash
set -uo pipefail; cd /ivi/zfs/s0/original_homes/ssalehi/SynthScope
export SYNTHSCOPE_CKPT_DIR=/hddstore/ssalehi/SynthScope/checkpoints HF_HOME=/hddstore/ssalehi/.cache/huggingface TORCH_HOME=/hddstore/ssalehi/.cache/torch SYNTHSCOPE_MFM_CKPT=/hddstore/ssalehi/SynthScope/mfm/mfm_pretrain_vit_base.pth CUDA_VISIBLE_DEVICES=4 OMP_NUM_THREADS=4
FULLG=/hddstore/ssalehi/SynthScope/GenImage_full/test_full
EV(){ conda run --no-capture-output -n SynthScope python benchmark/bench_eval.py "$@" 2>&1 | grep -vE "libpng|UserWarning|warnings.warn|Testing:|: 1[0-9]%|/375" | tail -6; }
echo "### VIB GenImage-8 (limit500) $(date)"; EV --model vib_net --ckpt checkpoints_retrain/vib_net/model_3.pth --benchmark pergen --data $FULLG --limit 500 --tag vib_v2_g8
echo "### flickr-recovery: co_spy.pth on 22 flickr subsets (clean) $(date)"; EV --model co_spy --benchmark pergen --data /hddstore/ssalehi/SynthScope/CoSpyBench/test --select "flickr__CompVis@ldm-text2im-large-256,flickr__CompVis@stable-diffusion-v1-4,flickr__PixArt-alpha@PixArt-XL-2-1024-MS,flickr__PixArt-alpha@PixArt-XL-2-512x512,flickr__black-forest-labs@FLUX.1-dev,flickr__black-forest-labs@FLUX.1-schnell,flickr__latent-consistency@lcm-lora-sdv1-5,flickr__latent-consistency@lcm-lora-sdxl,flickr__playgroundai@playground-v2-1024px-aesthetic,flickr__playgroundai@playground-v2-256px-base,flickr__playgroundai@playground-v2-512px-base,flickr__playgroundai@playground-v2.5-1024px-aesthetic,flickr__runwayml@stable-diffusion-v1-5,flickr__segmind@SSD-1B,flickr__segmind@SegMoE-SD-4x2-v0,flickr__segmind@small-sd,flickr__segmind@tiny-sd,flickr__stabilityai@sdxl-turbo,flickr__stabilityai@stable-diffusion-2,flickr__stabilityai@stable-diffusion-2-1,flickr__stabilityai@stable-diffusion-3-medium-diffusers,flickr__stabilityai@stable-diffusion-xl-base-1.0" --limit 200 --tag cospy_flickr_clean
echo "### FAST EVALS DONE $(date)"
